const examples=[{title:'오늘의 할 일',lines:['☑ 아이디어 모으기','☐ 첫 번째 초안 작성하기','☐ 결과 확인하고 다듬기'],reply:'좋아요. 할 일을 화면 옆에 붙여둘게요.',color:'#fffdf5'},{title:'지금까지의 진행 상황',lines:['☑ 자료 확인 완료','☑ 초안 작성 완료','☐ 마지막으로 검토하는 중'],reply:'초안까지 마쳤어요. 현재 진행 상황으로 메모를 갱신했어요.',color:'#eaf0d6'},{title:'다음에 이어갈 아이디어',lines:['작게 시작하고, 자주 다듬기.','완벽한 계획보다 첫 번째 시도.','다음 작업에서 이 생각 이어가기.'],reply:'좋은 생각이네요. 다음에 이어갈 수 있게 메모해둘게요.',color:'#f6e7cb'}];
document.querySelectorAll('[data-demo]').forEach(button=>button.addEventListener('click',()=>{const example=examples[Number(button.dataset.demo)];document.querySelectorAll('[data-demo]').forEach(item=>{const active=item===button;item.classList.toggle('selected',active);item.setAttribute('aria-pressed',String(active))});document.querySelector('#note-title').textContent=example.title;document.querySelector('#note-body').replaceChildren(...example.lines.map(line=>{const p=document.createElement('p');p.textContent=line;return p}));document.querySelector('.agent-reply').textContent=example.reply;document.querySelector('.demo-note').style.background=example.color;document.querySelector('#note-status').textContent='에이전트가 방금 갱신했어요'}));
